alter table discovery_runs add column progress jsonb check(progress is null or (jsonb_typeof(progress)='object' and octet_length(progress::text)<=5000));
create function hosted_discovery_progress(p_id uuid,p_claim uuid,p_progress jsonb) returns boolean language plpgsql security definer set search_path=pg_catalog,public as $$
begin
 if p_progress is null or jsonb_typeof(p_progress->'sources') is distinct from 'array' or jsonb_array_length(p_progress->'sources')>7 or octet_length(p_progress::text)>5000 then raise exception using errcode='P0001',message='invalid_progress';end if;
 if exists(select 1 from jsonb_object_keys(p_progress) k where k<>'sources') or exists(select 1 from jsonb_array_elements(p_progress->'sources') e where jsonb_typeof(e) is distinct from 'object' or coalesce(e->>'source','') not in ('workday','greenhouse','lever','ashby','icims','bamboohr','paylocity') or coalesce(e->>'state','') not in ('queued','running','finished','failed','timed_out') or jsonb_typeof(e->'elapsedMs') is distinct from 'number' or jsonb_typeof(e->'matches') is distinct from 'number' or jsonb_typeof(e->'boardsScanned') is distinct from 'number' or exists(select 1 from jsonb_object_keys(e) k where k not in ('source','state','elapsedMs','matches','boardsScanned'))) then raise exception using errcode='P0001',message='invalid_progress';end if;
 if (select count(distinct e->>'source') from jsonb_array_elements(p_progress->'sources') e)<>jsonb_array_length(p_progress->'sources') or exists(select 1 from jsonb_array_elements(p_progress->'sources') e where (e->>'elapsedMs')::numeric not between 0 and 300000 or (e->>'matches')::numeric not between 0 and 50 or (e->>'boardsScanned')::numeric not between 0 and 500) then raise exception using errcode='P0001',message='invalid_progress';end if;
 update public.discovery_runs set progress=p_progress||jsonb_build_object('reportedAt',clock_timestamp()) where id=p_id and claim=p_claim and state='running' and lease_until>clock_timestamp() and expires_at>clock_timestamp();return found;
end $$;
revoke all on function hosted_discovery_progress(uuid,uuid,jsonb) from public;
grant execute on function hosted_discovery_progress(uuid,uuid,jsonb) to career_discovery;
